// Generates supabase/seed.sql from the in-repo catalog (src/lib/products.ts and
// the vendor menus). Run: npx tsx scripts/generate-seed.ts
import { writeFileSync } from "node:fs";
import { products } from "../src/lib/products";
import { vendors } from "../src/lib/menus";

const q = (s: string | undefined) => (s == null ? "null" : `'${s.replace(/'/g, "''")}'`);
const arr = (a: string[]) => `array[${a.map(q).join(",")}]::text[]`;

const out: string[] = [
  "-- Generated by scripts/generate-seed.ts. Do not edit by hand.",
  "insert into vendors (slug, name) values",
  vendors.map((v) => `  (${q(v.id)}, ${q(v.name)})`).join(",\n") + "\non conflict (slug) do nothing;",
  "",
  // Food items: description and tags are derived in SQL to keep the seed small.
  "insert into products (slug, name, category, vendor_id, subcategory, price_naira, description, unit, image_emoji, tags)",
  "select f.slug, f.name, 'food', v.id, f.sub, f.price, f.name || ' from ' || v.name || '.', f.unit, f.emoji,",
  "  array[lower(f.sub), lower(v.name)]",
  "from (values",
  products
    .filter((p) => p.category === "food")
    .map((p) => `  (${q(p.vendorId)}, ${q(p.slug)}, ${q(p.name)}, ${q(p.subcategory)}, ${p.priceNaira}, ${q(p.unit)}, ${q(p.imageEmoji)})`)
    .join(",\n"),
  ") as f(vendor, slug, name, sub, price, unit, emoji)",
  "join vendors v on v.slug = f.vendor",
  "on conflict (slug) do nothing;",
  "",
  "insert into products (slug, name, category, subcategory, price_naira, compare_at_naira, description, requires_prescription, unit, image_url, image_emoji, tags, in_stock) values",
  products
    .filter((p) => p.category === "pharmacy")
    .map(
      (p) =>
        `  (${q(p.slug)}, ${q(p.name)}, 'pharmacy', ${q(p.subcategory)}, ${p.priceNaira}, ${p.compareAtNaira ?? "null"}, ${q(p.description)}, ${
          p.requiresPrescription ? "true" : "false"
        }, ${q(p.unit)}, ${q(p.imageUrl)}, ${q(p.imageEmoji)}, ${arr(p.tags)}, ${p.inStock ? "true" : "false"})`
    )
    .join(",\n") + "\non conflict (slug) do nothing;",
  "",
  "-- Keep the menu order (pharmacy first, then each restaurant's menu in order).",
  "update products p set sort_order = o.n",
  "from (values",
  products.map((p, i) => `  (${q(p.slug)}, ${i + 1})`).join(",\n"),
  ") as o(slug, n)",
  "where p.slug = o.slug;",
  "",
];
writeFileSync("supabase/seed.sql", out.join("\n"));
console.log(`vendors=${vendors.length} products=${products.length}`);
